select 'care', 'Call My Doctor Health Care LLC', 'Call My Doctor Health Care LLC', 'دبي', 'البرشا 1', '+971 4 549 0700', 'https://callmydoctor.ae', null, 'شركة رعاية صحية منزلية في دبي تقدّم زيارات الأطباء والتمريض والعلاج الطبيعي في المنزل.', 'https://callmydoctor.ae/about-us/', 'كول ماي دكتور للرعاية الصحية شركة في دبي تقدّم خدمات الطبيب في المنزل والفندق والتمريض المنزلي بما فيه رعاية الجروح ورعاية المسنين والرعاية التلطيفية. يذكر الموقع أن خدماتها يقدّمها مهنيون طبيون مرخّصون من هيئة الصحة بدبي.', 'https://callmydoctor.ae/wp-content/uploads/2026/01/Cmd-Logo-White.png', null, 'مركز AB، شارع الشيخ زايد، البرشا 1، دبي', null, array['التمريض المنزلي ورعاية الجروح', 'العلاج الطبيعي في المنزل', 'علاج النطق في المنزل', 'طبيب أطفال في المنزل', 'التحاليل المخبرية في المنزل']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'care' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Call My Doctor Health Care LLC'));
