select 'care', 'DarDoc', 'DarDoc', 'أبوظبي', 'جزيرة المارية', '+971 800 327362867', 'https://www.dardoc.com', 2021, 'منصة رعاية صحية منزلية تقدّم التمريض المنزلي ورعاية المسنين والمواليد في الإمارات.', 'https://www.dardoc.com/', 'دار دوك منصة رقمية للرعاية الصحية المنزلية تشغّلها شركة مسجلة في سوق أبوظبي العالمي، احتضنتها دائرة الصحة – أبوظبي ومعتمدة لتقديم الخدمات عبر تطبيقها في أبوظبي. تقدّم التمريض المنزلي لرعاية المواليد والمسنين إلى جانب التحاليل المنزلية والمحاليل الوريدية.', 'https://www.dardoc.com/og-image.png', 'wecare@dardoc.com', 'الطابق 15، برج الخاتم، جزيرة المارية، أبوظبي', null, array['رعاية المواليد والتمريض الليلي', 'رعاية المسنين في المنزل', 'رعاية الأم بعد الولادة', 'التحاليل في المنزل', 'المحاليل الوريدية']::text[], 'المؤسس المشارك والرئيس التنفيذي سامر المصري.', true
where not exists (select 1 from public.service_providers where category = 'care' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('DarDoc'));
