select 'care', 'Manzil Healthcare Services', 'Manzil Healthcare Services', 'دبي', 'أم هرير 2', '+971 800 626945', 'https://manzilhealth.com', null, 'مزوّد رعاية صحية منزلية يقدّم التمريض ورعاية المسنين وجليسات الأطفال ومقدّمي الرعاية.', 'https://manzilhealth.com/mission-vision-and-values/', 'منزل للخدمات الصحية مزوّد رعاية صحية منزلية يذكر أن طاقمه يضم ممرضين وأطباء ومعالجين مرخّصين من دائرة الصحة أبوظبي ووزارة الصحة وهيئة الصحة بدبي. يذكر الموقع أنه حاصل على اعتماد اللجنة الدولية المشتركة (JCI) مرتين وجائزة الشيخ خليفة للامتياز.', 'https://manzilhealth.com/wp-content/uploads/2018/09/logo-1.png', 'info@manzilhealth.ae', 'مكتب 114، مجمع محاكم دبي، أم هرير 2، دبي', null, array['رعاية المسنين', 'خدمات جليسات الأطفال', 'خدمة مقدّمي الرعاية', 'التنفس الاصطناعي في المنزل', 'رعاية الأم والطفل']::text[], 'يذكر الموقع أن لديه أكثر من 360 موظفًا في الإمارات وقطر والكويت.', true
where not exists (select 1 from public.service_providers where category = 'care' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Manzil Healthcare Services'));
