select 'care', 'Enayati Home HealthCare Center LLC', 'Enayati Home HealthCare Center LLC', 'دبي', 'المركز التجاري 1', '+971 4 338 5990', 'https://enayati.ae', null, 'مركز رعاية صحية منزلية في دبي مرخّص من هيئة الصحة بدبي يقدّم رعاية المسنين والتمريض.', 'https://enayati.ae/', 'عنايتي للرعاية الصحية المنزلية مركز خاص في دبي يذكر أنه مرخّص من هيئة الصحة بدبي وحاصل على اعتماد CARF الدولي. يقدّم رعاية المسنين والخرف والتمريض المنزلي والرعاية التلطيفية ورعاية المحتضرين في دبي والشارقة.', 'https://enayati.ae/wp-content/uploads/2026/09/Enayati-Logo-Web-1.webp', 'info@enayati.org', '2501 برج الموسى 2، شارع الشيخ زايد، المركز التجاري 1، دبي', null, array['رعاية المسنين', 'رعاية مرضى الخرف', 'الرعاية التلطيفية', 'رعاية المحتضرين', 'علاج النطق']::text[], 'الشركاء المؤسسون ممرضون كبار من كندا والمملكة المتحدة يقيمون في الإمارات منذ أكثر من 30 عامًا.', true
