select 'care', 'Homspital (Cornerstone Home Health Care LLC)', 'Homspital (Cornerstone Home Health Care LLC)', 'دبي', 'القرهود', '+971 6 731 1919', 'https://homspital.com', null, 'مزوّد رعاية صحية منزلية تديره كورنرستون للرعاية الصحية المنزلية ويقدّم رعاية المسنين والتمريض.', 'https://homspital.com/sharjah/', 'هومسبيتال علامة تشغّلها شركة كورنرستون للرعاية الصحية المنزلية ذ.م.م، ويذكر الموقع أنها مرخّصة من هيئة الصحة بدبي إلى جانب مركز كورنرستون لتطوير الصحة في عجمان المرخّص من وزارة الصحة ووقاية المجتمع. تقدّم التمريض المنزلي والرعاية طويلة الأمد ورعاية المسنين والرعاية التلطيفية.', 'https://homspital.com/wp-content/uploads/2026/02/Homspital-logo-H.png', 'info@homspital.com', 'الدرة 4، مكتب 204، القرهود، دبي', 'https://goo.gl/maps/Zc8UrJvjtzN57yfP9', array['التمريض المنزلي', 'الرعاية المعقّدة طويلة الأمد', 'رعاية المسنين', 'الرعاية التلطيفية', 'رعاية الأم والطفل']::text[], null, true
