select 'domestic', 'Excellence Center Tadbeer (Excellence Domestic Workers Services)', 'Excellence Center Tadbeer (Excellence Domestic Workers Services)', 'دبي', 'القوز 3', '+971 4 347 4000', 'https://excellencecenter.ae/', null, 'مركز تدبير في دبي لاستقدام وتشغيل العمالة المساعدة وإنجاز تأشيرات الخادمات.', 'https://excellencecenter.ae/', 'يصف المركز نفسه بأنه مركز تدبير مرخص من وزارة الموارد البشرية والتوطين في دبي. يوفر استقدام الخادمات والمربيات والسائقين والطهاة والبستانيين والمدرسين الخصوصيين، مع خدمات التأشيرة والفحص الطبي والتأمين والهوية الإماراتية. يعمل يوميًا من 8 صباحًا حتى 8 مساءً.', null, null, 'محل رقم 2، شارع 23، القوز 3، دبي', null, array['استقدام خادمات بكفالة تدبير', 'توفير عمالة تحت كفالة الأسرة', 'خدمات تأشيرة الخادمات', 'تدريب العمالة المساعدة', 'تجديد وإلغاء التأشيرات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Excellence Center Tadbeer (Excellence Domestic Workers Services)'));
