select 'movers', 'ISS Relocations', 'ISS Relocations', 'دبي', 'Al Quoz Industrial Area 1', '+971 4 234 8100', 'https://iss-relocations.com/', null, 'شركة نقل في دبي تقدم نقل المنازل والمكاتب والنقل الدولي والتغليف والتخزين والتخليص الجمركي.', 'https://iss-relocations.com/', 'تقدم ISS Relocations نقل المنازل والمكاتب والانتقال الدولي مع التغليف والتخزين والتخليص الجمركي. وتذكر أن نشاطها بدأ عام 1996 باسم Mac Movers ضمن Mackenzie Logistics. وتعلن أنها معتمدة من FIDI وحاصلة على ISO 9001 وISO 14001، ولها مكتب في أبوظبي أيضًا.', 'https://iss-relocations.com/wp-content/uploads/2025/05/ISS-Relocations-Best-Moving-Services-in-Dubai.svg', 'uae@iss-relocations.com', 'مجمع UPS، مستودع B2-14، منطقة القوز الصناعية 1، ص.ب 122511، دبي', 'https://share.google/28QZhYZcy0abn9d8K', array['نقل المنازل والمكاتب', 'الانتقال الدولي والشحن', 'التغليف والتخزين', 'شحن السيارات ونقل الحيوانات الأليفة', 'إدارة السجلات وتجهيز الفنادق']::text[], 'تذكر الشركة أن موظفيها مدرَّبون وخضعوا لفحص الخلفية.', true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('ISS Relocations'));
