select 'movers', 'E-Movers LLC', 'E-Movers LLC', 'دبي', null, '+971 4 341 7042', 'https://emoversuae.com/', 2003, 'شركة نقل تعمل منذ 2003 في دبي والشارقة وأبوظبي لنقل المنازل والمكاتب والنقل الدولي والتخزين.', 'https://emoversuae.com/', 'تعمل E-Movers منذ 2003 في نقل المنازل والمكاتب والانتقال الدولي وتركيب الأثاث. وتوفر تخزينًا قصير وطويل الأمد في منشأة تزيد على 100,000 قدم مربعة. ولها رقم هاتف في أبوظبي إلى جانب دبي.', 'https://emoversuae.com/wp-content/themes/emovers-revamp/images/emove-logo-new-v1.png', 'mail@emoversuae.com', null, null, array['نقل المنازل والمكاتب', 'الانتقال الدولي', 'التخزين', 'نقل الأعمال الفنية', 'خدمة عاملات تغليف']::text[], 'تذكر الشركة أن لديها أكثر من 500 موظف وأكثر من 100 مركبة.', true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('E-Movers LLC'));
